 const [data,setData]=useState<any>(null),[view,setView]=useState('Overview'),[cid,setCid]=useState(''),[search,setSearch]=useState(''),[category,setCategory]=useState('All documents'),[modal,setModal]=useState(''),[draft,setDraft]=useState<any>({}),[selected,setSelected]=useState<R|null>(null),[thread,setThread]=useState(''),[reply,setReply]=useState(''),[attachments,setAttachments]=useState<string[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[toast,setToast]=useState(''),[mobile,setMobile]=useState(false),[month,setMonth]=useState(new Date().toISOString().slice(0,7)),[work,setWork]=useState<W|null>(null),[track,setTrack]=useState({company:'',category:'All',status:'All',sort:'due'}),[reqId,setReqId]=useState(''),[reqNote,setReqNote]=useState(''),[reqFilter,setReqFilter]=useState('All'),[reqCompany,setReqCompany]=useState(''),[loadingView,setLoadingView]=useState(false),[viewError,setViewError]=useState('');const ref=useRef<HTMLDivElement>(null);
 async function load(){const r=await fetch('/api/portal'),d:any=await r.json();if(!r.ok)throw new Error(d.error);setData(d);setCid(old=>d.companies.some((c:R)=>c.id===old)?old:d.companies[0]?.id||'');return d;}
 useEffect(()=>{load().catch(e=>setError(e.message))},[actor.id]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';const frame=requestAnimationFrame(()=>ref.current?.querySelector<HTMLElement>('button,input')?.focus());const keys=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)setModal('');if(e.key==='Tab'){const all=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')||[]).filter(x=>x.offsetParent!==null);if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus()}}};window.addEventListener('keydown',keys);return()=>{cancelAnimationFrame(frame);document.body.style.overflow=old;window.removeEventListener('keydown',keys);previous?.focus()}},[modal,busy]);
 const staff=!!data?.staff,canWrite=staff||actor.role==='Client';const company:R|undefined=data?.companies.find((c:R)=>c.id===cid);const docs:R[]=data?.documents.filter((r:R)=>r.company===cid)||[],shared=docs.filter(d=>d.shared),current=shared.filter(d=>!d.supersededBy),onboarding=data?.cases.find((r:R)=>r.company===cid);const obligations:R[]=data?.obligations.filter((r:R)=>r.company===cid)||[],invoices:R[]=data?.invoices.filter((r:R)=>r.company===cid)||[],payments:R[]=data?.payments.filter((r:R)=>r.company===cid)||[],threads:R[]=data?.threads.filter((r:R)=>r.company===cid)||[],alerts:R[]=data?.alerts.filter((r:R)=>r.company===cid)||[];const allRequests=((data?.work||[]) as W[]).filter(w=>w.source==='request'),companyRequests=allRequests.filter(w=>w.company===cid),reqItems=reqCompany==='all'?allRequests:allRequests.filter(w=>w.company===(reqCompany||cid)),reqShown=reqItems.filter(w=>(reqFilter==='All'||w.request?.status===reqFilter)&&(!search||[w.title,w.request?.description||''].join(' ').toLowerCase().includes(search.toLowerCase()))),openRequest=allRequests.find(w=>w.id===reqId);const items:W[]=((data?.work||[]) as W[]).filter(w=>track.company==='all'||w.company===(track.company||cid)),categories=Array.from(new Set(items.map(w=>w.category))).sort(),statuses=Array.from(new Set(items.map(w=>w.status).filter(Boolean))).sort(),tracked=items.filter(w=>(track.category==='All'||w.category===track.category)&&(track.status==='All'||w.status===track.status)&&(!search||w.title.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>track.sort==='updated'?String(b.updated||'').localeCompare(String(a.updated||'')):String(a.due||'9999').localeCompare(String(b.due||'9999'))),count=(s:string)=>tracked.filter(w=>w.status===s).length;const names2=(id:string|null)=>data.companies.find((c:R)=>c.id===id)?.name||'Your company';const conversation=threads.find(t=>t.id===thread);const confirmed=onboarding?.stages.filter((s:any)=>s.status==='Verified').length||0;const totalDue=invoices.filter(i=>i.status==='Issued').reduce((n,i)=>n+i.balance,0);const download=(mode:string,id='')=>'/api/portal?export='+mode+'&company='+encodeURIComponent(cid)+(id?'&id='+id:'');
