 function choice(key:string,label:string,values:string[]){return <label className="field"><span>{label}</span><select value={draft[key]||''} onChange={e=>setDraft({...draft,[key]:e.target.value})}><option value="">Choose…</option>{values.map(v=><option key={v}>{v}</option>)}</select></label>}
 function evidence(key='evidence'){return <div className="portal-evidence"><h3>Supporting documents</h3><p className="muted">Upload files to Documents first. Only current, client-visible files can be attached.</p>{current.map(d=><label className="check-row" key={d.id}><input type="checkbox" checked={(draft[key]||[]).includes(d.id)} onChange={e=>setDraft({...draft,[key]:e.target.checked?[...(draft[key]||[]),d.id]:draft[key].filter((id:string)=>id!==d.id)})}/>{d.name}</label>)}{!current.length&&<p className="inline-note">No published documents yet.</p>}</div>}
 async function submit(e:React.FormEvent){e.preventDefault();const r=selected;switch(modal){case'company':{const result=await act(r?'companySave':'companyCreate',{...(r?identity(r):{}),data:draft,clientName:draft.clientName,clientEmail:draft.clientEmail,clientPassword:draft.clientPassword,clientConfirmPassword:draft.clientConfirmPassword});if(result?.id)setCid(result.id);break}case'stage':await act('stageUpdate',{...identity(r!),stage:draft.stage,status:draft.status,due:draft.due,note:draft.note,evidence:draft.evidence});break;case'obligation':await act(r?'obligationSave':'obligationCreate',{...(r?identity(r):{}),data:draft});break;case'plan':await act('annualPlan',{period:draft.period});break;case'publishTask':await act('publishTask',{task:draft.task,note:draft.note});break;case'thread':{const result=await act('threadCreate',draft);if(result){setThread(result.id);go('Inbox')}break}case'invoice':await act('invoiceCreate',{data:draft});break;case'payment':await act('paymentReport',{...identity(r!),...draft});break;case'document':await act('documentPublish',{...identity(r!),category:draft.category,period:draft.period,shared:draft.shared});break;}}
